#include <stdio.h>
static int clock_value, d[3], f[3];
static void dfs(int u)
{
    d[u]=++clock_value;
    if(u+1<3) { dfs(u+1); }
    f[u]=++clock_value;
}
int main(void)
{
    dfs(0);
    printf("%d\n",f[0]);
    return 0;
}

